import{_ as a,o as t,c as n,ak as r}from"./chunks/framework.B8jO0odJ.js";const g=JSON.parse('{"title":"GAME DESIGN DOCUMENT","description":"!Chainy logo","frontmatter":{"title":"GAME DESIGN DOCUMENT","description":"!Chainy logo","source":"docs/game-design.md","category":"Game & system design","sourceUpdated":"2026-10-08T07:30:14+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/game-design.md","filePath":"content/docs/game-design.md"}'),o={name:"content/docs/game-design.md"};function i(s,e,d,c,l,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<div><h1 id="game-design-document">GAME DESIGN DOCUMENT<a class="header-anchor" href="#game-design-document" aria-label="Link to this section">​</a></h1><h2 id="chainy-a-3d-world-educational-game-for-learning-emerging-technology-blockchain--ai">Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain &amp; AI)<a class="header-anchor" href="#chainy-a-3d-world-educational-game-for-learning-emerging-technology-blockchain--ai" aria-label="Link to this section">​</a></h2><p><img src="/Chainy-Docs/attachments/docs/media/brand/chainy-logo.png" alt="Chainy logo"></p><p><strong>Short game name:</strong> Chainy <strong>Design edition:</strong> October 8, 2026 <strong>Audience:</strong> Learners aged 12–17 <strong>Format:</strong> Offline Android educational game</p><p>This illustrated outline follows the supplied <em>Project Vanishing</em> example while retaining Chainy&#39;s approved purpose and gameplay. Images show design proposals, not completed software.</p><p>The three worlds, offline approach and visual identity are confirmed. Lesson names, nine-lesson arrangement, completion rules and small presentation details are proposed for review and testing.</p><h2 id="contents">Contents<a class="header-anchor" href="#contents" aria-label="Link to this section">​</a></h2><ol><li>Game objectives and brief</li><li>Gameplay</li><li>Game world</li><li>Art, interface, storyboard and sound</li><li>Game mechanics</li><li>Characters and player definition</li><li>Project plan</li><li>References and supporting documents</li></ol><h2 id="1-game-objectives-and-brief">1. Game objectives and brief<a class="header-anchor" href="#1-game-objectives-and-brief" aria-label="Link to this section">​</a></h2><h3 id="11-game-brief">1.1 Game brief<a class="header-anchor" href="#11-game-brief" aria-label="Link to this section">​</a></h3><p>Chainy introduces essential ideas about <strong>Web3, Blockchain and AI</strong> through short illustrated lessons and puzzles. It is designed especially for learners in low-income and remote communities with limited access to technology. The game assumes neither previous knowledge of these subjects nor personal ownership of a phone.</p><p>The player taps one of three worlds, meets a friendly guide and works through an everyday situation. They might decide whether a message is safe, put delivery records in order, compare different copies of a record, or help a robot deliver a parcel. Each choice produces an explanation and a chance to try again.</p><p><strong>Genre:</strong> Single-player educational lesson-and-puzzle game. <strong>Player:</strong> One learner at a time, with separate local profiles for shared devices. <strong>Game elements:</strong> Choosing, sorting, ordering, linking, comparing, predicting, revising and answering short questions.</p><h3 id="12-narrative-brief">1.2 Narrative brief<a class="header-anchor" href="#12-narrative-brief" aria-label="Link to this section">​</a></h3><p>A blue-haired explorer in a yellow coat welcomes the learner to a small technology learning community. Its three worlds make unfamiliar ideas visible: Web3 World explores information and safe choices; Blockchain World examines records and shared copies; AI World investigates examples, predictions and actions.</p><p>Practical stories motivate each lesson: a club reviews who can change its list, a delivery record has been altered, or a sorting helper makes a mistake. The learner inspects the situation and decides what to do.</p><h3 id="13-game-objectives">1.3 Game objectives<a class="header-anchor" href="#13-game-objectives" aria-label="Link to this section">​</a></h3><p>The intended learner can:</p><ul><li>Ask who controls information and recognize requests that should be checked carefully.</li><li>Explain why records need an order and how a saved reference helps reveal a change.</li><li>Compare three copies using the lesson&#39;s stated rule and recognize when that rule cannot choose an answer.</li><li>Distinguish examples used for learning from new examples used for checking a prediction.</li><li>Explain a simple robot&#39;s observation, chosen action and result.</li></ul><p>Finishing a lesson is evidence of completing its activities, not proof of expertise. Actual learner understanding, readability and enjoyment must be evaluated with the intended audience.</p><h2 id="2-gameplay">2. Gameplay<a class="header-anchor" href="#2-gameplay" aria-label="Link to this section">​</a></h2><h3 id="21-playing-chainy">2.1 Playing Chainy<a class="header-anchor" href="#21-playing-chainy" aria-label="Link to this section">​</a></h3><p>You open Chainy without connecting to the internet. After choosing your learner profile, the explorer welcomes you to a colorful map. You tap Blockchain World and open a lesson about delivery records. The guide shows a short example, then gives you three new cards: Pack, Dispatch and Receive.</p><p>You place Receive before Dispatch and press Check. The game highlights the problem: “This receipt has no earlier dispatch.” You inspect the cards, change the order and connect the records. The guide explains why your correction works. Three short questions ask you to apply the idea again. Once your result is saved, the lesson card shows your progress and you can return to the map.</p><h3 id="22-opening-options-and-modes">2.2 Opening, options and modes<a class="header-anchor" href="#22-opening-options-and-modes" aria-label="Link to this section">​</a></h3><p>The opening menu offers <strong>Play</strong>, <strong>Continue</strong> and <strong>Settings</strong>. On a shared phone, the teacher provides a learner code so each person can select their own local progress. Entering the same code on another phone does not bring an earlier save to that phone.</p><p>Play opens the world map. Continue returns to the learner&#39;s last saved point. Settings include sound and readability options. Pause offers Resume, Return to Map and Switch Learner. Switching clearly identifies that the current session is ending.</p><p>There is one guided learning journey, with replay of completed lessons. Teacher export is a separate staff activity. No multiplayer, online account, purchase or cryptocurrency transaction is needed.</p><h3 id="23-the-lesson-loop">2.3 The lesson loop<a class="header-anchor" href="#23-the-lesson-loop" aria-label="Link to this section">​</a></h3><p><img src="/Chainy-Docs/attachments/docs/media/gdd/presentation/lesson-flow.png" alt="A lesson begins with a choice, continues through an example and activity, and ends with feedback and saved progress"></p><p><strong>Figure 1. Proposed lesson flow. A mistaken answer returns the learner to an explanation and another attempt.</strong></p><p>A typical lesson follows six steps: choose a lesson; read a short explanation; inspect an example; try the activity; review the outcome; answer fresh questions and save. Help remains available. Learners can pause rather than rush through an unfamiliar term.</p><h3 id="24-winning-losing-and-the-ending">2.4 Winning, losing and the ending<a class="header-anchor" href="#24-winning-losing-and-the-ending" aria-label="Link to this section">​</a></h3><p>A lesson is completed after its required activity and understanding check. The proposed check contains three questions: answer all three and correctly answer at least two, with explanations and retries. Repeating one correct question does not count as answering another. The result must be saved before completion appears.</p><p>There is no death, health loss or permanent failure. A wrong choice, broken link or blocked robot is an invitation to inspect and revise. Previously earned progress is retained. Completing the agreed foundation lessons opens a journey summary, followed by replay or exit.</p><h3 id="25-why-the-game-should-be-enjoyable">2.5 Why the game should be enjoyable<a class="header-anchor" href="#25-why-the-game-should-be-enjoyable" aria-label="Link to this section">​</a></h3><p>Short challenges, predictions and visible consequences encourage curiosity. Revision gives the learner control over improvement. Friendly characters and progress support the journey. These intentions need learner testing.</p><h2 id="3-game-world">3. Game world<a class="header-anchor" href="#3-game-world" aria-label="Link to this section">​</a></h2><h3 id="31-the-three-world-map">3.1 The three-world map<a class="header-anchor" href="#31-the-three-world-map" aria-label="Link to this section">​</a></h3><p><img src="/Chainy-Docs/attachments/docs/media/gdd/presentation/world-map.png" alt="Three tappable learning worlds: Web3, Blockchain and AI"></p><p><strong>Figure 2. Proposed map presentation. Tap a world to open its lesson cards; the map does not require walking or a joystick.</strong></p><p>All three worlds are visible. Their first lessons are available after a brief touch-control introduction. Later lessons follow a suggested order within their own world; completed lessons can be replayed. Web3 is a useful starting point, but learners do not have to finish it before opening Blockchain or AI.</p><p>The <strong>nine-lesson draft</strong> is a proposal, not a confirmed count. The proposed three-to-five-minute lessons need learner testing, including reading support and retries.</p><h3 id="32-web3-world">3.2 Web3 World<a class="header-anchor" href="#32-web3-world" aria-label="Link to this section">​</a></h3><p>Familiar community examples introduce control, privacy and safe decisions. Web3 scenery follows Chainy&#39;s rounded style; its details remain proposed.</p><table><thead><tr><th>Proposed lesson</th><th>What the learner does</th></tr></thead><tbody><tr><td>Who Controls the Information?</td><td>Compare a list controlled by one person with shared responsibility, then ask who can approve changes.</td></tr><tr><td>Public Information and Secrets</td><td>Sort fictional information into appropriate sharing choices; distinguish a receiving address from a secret.</td></tr><tr><td>Pause and Check</td><td>Inspect suspicious messages, recognize pressure or secret requests, and choose a safe next step.</td></tr></tbody></table><p>The game uses pretend information. It never asks learners to enter real passwords, private keys, home addresses or payment details.</p><h3 id="33-blockchain-world">3.3 Blockchain World<a class="header-anchor" href="#33-blockchain-world" aria-label="Link to this section">​</a></h3><p>Blue and green island scenery frames clear record cards and friendly robot guidance. The learning area focuses attention on events, links and copies rather than a large landscape.</p><table><thead><tr><th>Proposed lesson</th><th>What the learner does</th></tr></thead><tbody><tr><td>Put the Records in Order</td><td>Arrange Pack, Dispatch and Receive using a stated rule, then link neighboring records.</td></tr><tr><td>Find the Changed Record</td><td>Compare a current record with a saved reference, identify the difference and check a correction.</td></tr><tr><td>Compare Three Copies</td><td>Inspect three copies, preview a repair and recognize a case with no agreement.</td></tr></tbody></table><p>The examples explain limited classroom rules. They do not claim that matching copies or a hash proves an event happened in the real world.</p><h3 id="34-ai-world">3.4 AI World<a class="header-anchor" href="#34-ai-world" aria-label="Link to this section">​</a></h3><p>Violet scenery and cyan highlights distinguish AI World while preserving the same characters and interface. Fictional parcels make examples, features and decisions concrete.</p><table><thead><tr><th>Proposed lesson</th><th>What the learner does</th></tr></thead><tbody><tr><td>Teach with Examples</td><td>Label practice parcels, train a small sorting model and test a fresh parcel.</td></tr><tr><td>Learn from a Mistake</td><td>Inspect an incorrect label, revise the examples and compare the changed prediction.</td></tr><tr><td>Guide a Simple Agent</td><td>Arrange a short sequence of commands and help a robot deliver a parcel on a small grid.</td></tr></tbody></table><p>The sorting activity must genuinely learn from the supplied examples and work clearly on a phone before it becomes production content. It must not present fixed answers as learned predictions.</p><h2 id="4-art-interface-storyboard-and-sound">4. Art, interface, storyboard and sound<a class="header-anchor" href="#4-art-interface-storyboard-and-sound" aria-label="Link to this section">​</a></h2><h3 id="41-art-direction">4.1 Art direction<a class="header-anchor" href="#41-art-direction" aria-label="Link to this section">​</a></h3><p>The first two supplied Chainy storyboards are the visual authority: rounded toy-like 3D characters, soft lighting, a blue-haired explorer in yellow, friendly screen-faced robots, chunky scenery and welcoming colors. Keep this identity while using respectful explanations suited to ages 12–17.</p><p>The third, BlockForge image contributes gameplay ideas only. Its flat illustration style, title, money rewards and certificate are not adopted. Likewise, the fantasy setting, combat and keyboard controls of <em>Project Vanishing</em> are not Chainy features; that document guides this outline and illustrated presentation.</p><p>Artwork highlights the current action. Final instructions, quantities and answers come from reviewed lesson content, not decorative text.</p><h3 id="42-interface-and-controls">4.2 Interface and controls<a class="header-anchor" href="#42-interface-and-controls" aria-label="Link to this section">​</a></h3><p><img src="/Chainy-Docs/attachments/docs/media/gdd/presentation/controls.png" alt="Illustrated touch controls for choosing lessons, selecting answers, checking and returning"></p><p><strong>Figure 3. Proposed touch interface. Clearly labeled buttons provide an alternative to dragging.</strong></p><p>The learner taps world and lesson cards, advances short explanations and selects an answer. Ordering uses selectable cards with earlier/later controls; dragging may be offered as an additional choice. A clear Check button tests the current answer. Back, Help and Pause remain easy to find.</p><p>The main screens are the learner profile, menu, world map, lesson introduction, activity, feedback, understanding check, progress summary and settings. Staff export is visually separate. Important text must fit on the phone with larger text enabled; colors always have labels or symbols to explain their meaning.</p><h3 id="43-storyboard">4.3 Storyboard<a class="header-anchor" href="#43-storyboard" aria-label="Link to this section">​</a></h3><p><img src="/Chainy-Docs/attachments/docs/media/gdd/presentation/lesson-storyboard.png" alt="Illustrated sequence from choosing a world through trying an activity to receiving feedback and progress"></p><p><strong>Figure 4. Proposed player journey. Each scene serves one step of the learning experience.</strong></p><p>The panels show welcome, objective/example, learner activity, explanatory feedback, a fresh check and saved progress. Reusing this sequence lets learners focus on each new concept without relearning the interface.</p><h3 id="44-sound-and-accessibility">4.4 Sound and accessibility<a class="header-anchor" href="#44-sound-and-accessibility" aria-label="Link to this section">​</a></h3><p>Use short sounds for selecting an item, checking an answer and completing a lesson. Optional gentle music may establish the world&#39;s mood. Sounds remain secondary to visible feedback, and every required instruction works with audio muted. Narration is not assumed.</p><p>Begin with an unscored touch practice. Use plain English, one instruction at a time and meaningful pictures. A teacher may read instructions without choosing answers for the learner. Do not confuse unfamiliarity with a phone, slow reading or asking for help with poor understanding of the concept.</p><h2 id="5-game-mechanics">5. Game mechanics<a class="header-anchor" href="#5-game-mechanics" aria-label="Link to this section">​</a></h2><h3 id="51-lesson-guidance-and-choices">5.1 Lesson guidance and choices<a class="header-anchor" href="#51-lesson-guidance-and-choices" aria-label="Link to this section">​</a></h3><p>A guide presents a goal, one worked example and a small task. The learner predicts an outcome before checking it. Scenario activities ask the learner to compare, select or sort fictional items. Feedback names the reason: “This message asks for a secret,” or “This receipt needs an earlier dispatch.” It does not merely show a red cross.</p><h3 id="52-records-changes-and-copies">5.2 Records, changes and copies<a class="header-anchor" href="#52-records-changes-and-copies" aria-label="Link to this section">​</a></h3><p><img src="/Chainy-Docs/attachments/docs/media/gdd/presentation/mechanics.png" alt="Illustrated examples of ordering records, comparing copies, learning from examples and guiding an agent"></p><p><strong>Figure 5. The core activities turn abstract ideas into visible choices and consequences.</strong></p><p>For record ordering, the learner uses the supplied cards and links. Pack must come before Dispatch, and Dispatch before Receive. This is a bounded puzzle; free placement of an unlimited set of components is deferred.</p><p>For change detection, a saved reference is shown beside the current record. A changed destination or quantity creates a visible mismatch. Restoring it repairs the exercise, but the explanation distinguishes a matching record from proof that a real delivery occurred.</p><p>For comparing copies, three panels represent copies stored on the same device. In the normal exercise, two matching valid copies suggest how to repair one changed copy. A separate case with three different copies shows why the simple rule cannot decide and needs the provided reference. No internet connection or real distributed network is involved.</p><h3 id="53-learning-from-examples">5.3 Learning from examples<a class="header-anchor" href="#53-learning-from-examples" aria-label="Link to this section">​</a></h3><p>The learner labels fictional parcels using visible characteristics, such as weight and fragility. Train uses those examples to form a small model. Test then asks about a parcel kept separate from the practice examples.</p><p>A deliberately incorrect label allows the learner to see a wrong or uncertain prediction. They inspect the examples, correct the label, train again and compare. More examples do not automatically mean better results. The lesson keeps the model&#39;s prediction separate from the guide&#39;s comparison answer and explains when the result is uncertain.</p><h3 id="54-the-delivery-agent">5.4 The delivery agent<a class="header-anchor" href="#54-the-delivery-agent" aria-label="Link to this section">​</a></h3><p>A small fixed grid contains a robot, parcel, obstacle and destination. Available commands include Move, Turn, Pick Up, Deliver and Stop. The learner arranges a short sequence, predicts the next action and presses Step or Run.</p><p>A move into an obstacle stops with an explanation. Reaching the destination alone is insufficient: the robot must carry and deliver the parcel. The learner can revise and restart. This robot follows visible commands; it does not learn its route from the parcel-sorting lesson.</p><h3 id="55-progress-rewards-and-recovery">5.5 Progress, rewards and recovery<a class="header-anchor" href="#55-progress-rewards-and-recovery" aria-label="Link to this section">​</a></h3><p>Lesson cards show available, in-progress and completed states. Badges acknowledge saved completion. They are not certificates, a currency or a public ranking. Replaying a lesson retains its earlier results and earned progress.</p><p>Pause and Return to Map use the latest saved point. If saving fails, the game explains the problem and offers another attempt instead of displaying false completion. Reset affects the current activity, not the learner&#39;s whole history. Teachers can export the approved learner records separately; saving an export file does not automatically transfer it or delete local progress.</p><h2 id="6-characters-and-player-definition">6. Characters and player definition<a class="header-anchor" href="#6-characters-and-player-definition" aria-label="Link to this section">​</a></h2><p><img src="/Chainy-Docs/attachments/docs/media/gdd/presentation/characters.png" alt="Character direction featuring the blue-haired explorer and friendly robots"></p><p><strong>Figure 6. Character presentation follows the approved Chainy identity. Names and small costume details remain proposed.</strong></p><h3 id="61-explorer-and-guides">6.1 Explorer and guides<a class="header-anchor" href="#61-explorer-and-guides" aria-label="Link to this section">​</a></h3><p>The explorer is a welcoming companion rather than a combat hero. Blue hair, a yellow coat and a small backpack provide a recognizable silhouette across the map and lesson panels. The learner controls choices and activities directly; walking this character through a world is not required.</p><p>Blocky is the proposed blockchain guide, helping the learner inspect records and copies. Aira is the proposed AI guide, encouraging predictions and careful checking. Friendly robot designs may share the same basic model. A guide can also present Web3 scenarios without requiring another full character.</p><h3 id="62-player-properties-and-feedback">6.2 Player properties and feedback<a class="header-anchor" href="#62-player-properties-and-feedback" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Property</th><th>How it changes and what the learner sees</th></tr></thead><tbody><tr><td>Selected lesson</td><td>Choosing a card updates the objective and available activity.</td></tr><tr><td>Current answer or arrangement</td><td>Selecting, ordering or linking updates the visible choice before Check.</td></tr><tr><td>Activity outcome</td><td>Checking reveals a success explanation or a useful correction.</td></tr><tr><td>Saved lesson progress</td><td>Completed work changes the lesson card and may award a badge.</td></tr><tr><td>Sound and readability preferences</td><td>Settings give an immediate, visible or audible response.</td></tr></tbody></table><p>Health and weapons do not apply. There is no combat, death penalty or equipment system. Information cards support a lesson rather than acting as health pickups. Rewards are understanding, saved progress and brief recognition of completion.</p><h3 id="63-character-behavior">6.3 Character behavior<a class="header-anchor" href="#63-character-behavior" aria-label="Link to this section">​</a></h3><p>Use restrained gestures such as greeting, pointing, thinking and celebrating. The guide should point toward the relevant record or choice and leave room for the explanation. A short reaction may acknowledge success, but it must not interrupt correction or cover the next action.</p><h2 id="7-project-plan">7. Project plan<a class="header-anchor" href="#7-project-plan" aria-label="Link to this section">​</a></h2><h3 id="71-platform-and-technical-specifications">7.1 Platform and technical specifications<a class="header-anchor" href="#71-platform-and-technical-specifications" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Field</th><th>Retained design target</th></tr></thead><tbody><tr><td>Technical form and view</td><td>Rounded 3D visual identity, tappable map, fixed activity views and 2D interface; landscape is proposed.</td></tr><tr><td>Platform and device</td><td>Android touchscreen phone; one player at a time.</td></tr><tr><td>Language</td><td>Unity/C# for development; English for the first version.</td></tr><tr><td>Phone specification</td><td>Android 10+/11+, 4 GB physical RAM, 64 GB total storage, ARM64, OpenGL ES 3.2 or Vulkan 1.1, entry-level-to-midrange GPU.</td></tr><tr><td>Saves and connectivity</td><td>Local SQLite saves; required lessons work offline. Installation, teacher file transfer and updates are separate.</td></tr></tbody></table><p>Android 11+ is the provisional test starting point, with Android 10 a compatibility candidate. These retained specifications are not verified support claims. Total phone storage is not the game&#39;s required space. Test actual phones before claiming support.</p><h3 id="72-team-and-parallel-work">7.2 Team and parallel work<a class="header-anchor" href="#72-team-and-parallel-work" aria-label="Link to this section">​</a></h3><p>Sherwin Limosnero coordinates scope and delivery. Christian Jude Villaber leads technical integration. Sean Matthew Narvaez leads learning documentation and research materials. Luis Cabrido III leads artwork. Miguel De Leon supports interface work, documentation and device checks.</p><p>Parallel assistance is divided into content writing, illustrations, gameplay activities, interface work and independent review. Each worker receives a defined output and owner. The reviewer checks that pictures, instructions and actual behavior agree before integration. Shared screens and final builds have one integration owner. Balanced work must reflect available hours; the earlier 520-hour estimate has not been recalculated for the revised scope.</p><h3 id="73-milestones-and-evidence">7.3 Milestones and evidence<a class="header-anchor" href="#73-milestones-and-evidence" aria-label="Link to this section">​</a></h3><table><thead><tr><th>Conditional checkpoint</th><th>Expected result</th></tr></thead><tbody><tr><td>October 9–11</td><td>First phone build with working save, reopen and export checks.</td></tr><tr><td>October 18</td><td>One complete lesson and a checked example-learning activity; research preparation advanced.</td></tr><tr><td>October 25–30</td><td>Remaining agreed lessons brought together; integrated beta candidate targeted for October 30.</td></tr><tr><td>October 31–November 2</td><td>Readiness checks and correction of blocking problems.</td></tr><tr><td>November 3–6</td><td>Possible beta at Tambunan National High School, Marinduque, subject to booking and required arrangements.</td></tr><tr><td>November 7–16</td><td>Fixes, evidence review, analysis and manuscript completion.</td></tr><tr><td>November 17–20</td><td>Rehearsal, backups and critical corrections.</td></tr><tr><td><strong>November 21, 2026</strong></td><td><strong>Confirmed pre-final defense.</strong></td></tr></tbody></table><p>The beta is an opportunity, not a confirmed appointment or completed evaluation. Lesson count and schedule depend on actual production and phone checks. A successful document or illustration does not prove a working game. The supplied rubric and its 32-point structure remain; the school&#39;s method for measuring 60-percent completion still needs clarification. Lessons or task counts cannot establish that percentage.</p><h2 id="8-references-and-supporting-documents">8. References and supporting documents<a class="header-anchor" href="#8-references-and-supporting-documents" aria-label="Link to this section">​</a></h2><ol><li><strong>Document presentation:</strong> The user-supplied 27-page <em>Project Vanishing</em> GDD informs the numbered outline and use of supporting visuals, not Chainy&#39;s gameplay features.</li><li><strong>Visual direction:</strong> The first two supplied Chainy storyboards define the character and world style. The third BlockForge image supplies gameplay context only. New illustrations are design proposals.</li><li><strong>Learning content:</strong> Selected concepts from the supplied <em>Web3 Encyclopedia</em>, checked against primary educational references; <em>Giggle Academy</em> provides a learning-format reference. Full A–Z coverage is outside the agreed scope.</li><li><strong>Concept accuracy:</strong> NIST blockchain material, Google machine-learning educational material, and relevant privacy and responsible-AI references inform the beginner explanations. Detailed source mapping is retained in the learning materials.</li><li><strong>Project decisions:</strong> The user&#39;s approved mission, retained phone specifications, school deliverables and November 21 deadline govern this design.</li></ol><p>For the complete lesson copy and questions, see <a href="/Chainy-Docs/content/docs/learning-foundations.html">beginner learning materials</a>. The <a href="/Chainy-Docs/content/docs/project-baseline.html">project baseline</a> records confirmed decisions and the <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">active plan</a> owns delivery dates. Detailed rules, examples, traceability and engineering links remain in the <a href="/Chainy-Docs/content/docs/design/game-mechanics-reference.html">game mechanics reference</a>. <a href="/Chainy-Docs/content/docs/media/gdd/readme.html">Media provenance</a> identifies reference and generated assets.</p></div>',1)])])}const m=a(o,[["render",i]]);export{g as __pageData,m as default};
